module tlb_wrapper_tb;

initial begin
  $vcdplusfile("tlb_wrapper_tb.dump.vpd");
  $vcdpluson(0, tlb_wrapper_tb);
  $vcdpluson(0, tlb_wrapper_tb.REF.itlb.TLB_ENTRIES_BEHAV);
  $vcdpluson(0, tlb_wrapper_tb.REF.drdtlb.TLB_ENTRIES_BEHAV);
  $vcdpluson(0, tlb_wrapper_tb.REF.dwr0tlb.TLB_ENTRIES_BEHAV);
  $vcdpluson(0, tlb_wrapper_tb.REF.dwr1tlb.TLB_ENTRIES_BEHAV);
end

localparam VA_BIT_WIDTH=32;
localparam PA_BIT_WIDTH=15;
localparam PAGE_SIZE_BYTES=4096;
localparam PAGE_BIT_WIDTH=$clog2(PAGE_SIZE_BYTES);
localparam VPN_BIT_WIDTH=VA_BIT_WIDTH-PAGE_BIT_WIDTH;
localparam PFN_BIT_WIDTH=PA_BIT_WIDTH-PAGE_BIT_WIDTH;

reg  [VPN_BIT_WIDTH-1:0]   ITLB_VPN;
reg  [VPN_BIT_WIDTH-1:0]   D_RD_TLB_VPN;
reg  [VPN_BIT_WIDTH-1:0]   D_WR0_TLB_VPN;
reg  [VPN_BIT_WIDTH-1:0]   D_WR1_TLB_VPN;

wire [PFN_BIT_WIDTH-1:0]   ITLB_PFN_OUT, ITLB_PFN_OUT_BEHAV;
wire ITLB_WRITE_DISABLE_OUT, ITLB_CACHE_ENABLE_OUT, ITLB_PAGE_FAULT_OUT;
wire ITLB_WRITE_DISABLE_OUT_BEHAV, ITLB_CACHE_ENABLE_OUT_BEHAV, ITLB_PAGE_FAULT_OUT_BEHAV;

wire [PFN_BIT_WIDTH-1:0]   D_RD_TLB_PFN_OUT, D_RD_TLB_PFN_OUT_BEHAV;
wire D_RD_TLB_WRITE_DISABLE_OUT, D_RD_TLB_CACHE_ENABLE_OUT, D_RD_TLB_PAGE_FAULT_OUT;
wire D_RD_TLB_WRITE_DISABLE_OUT_BEHAV, D_RD_TLB_CACHE_ENABLE_OUT_BEHAV, D_RD_TLB_PAGE_FAULT_OUT_BEHAV;

wire [PFN_BIT_WIDTH-1:0]   D_WR0_TLB_PFN_OUT, D_WR0_TLB_PFN_OUT_BEHAV;
wire D_WR0_TLB_WRITE_DISABLE_OUT, D_WR0_TLB_CACHE_ENABLE_OUT, D_WR0_TLB_PAGE_FAULT_OUT;
wire D_WR0_TLB_WRITE_DISABLE_OUT_BEHAV, D_WR0_TLB_CACHE_ENABLE_OUT_BEHAV, D_WR0_TLB_PAGE_FAULT_OUT_BEHAV;

wire [PFN_BIT_WIDTH-1:0]   D_WR1_TLB_PFN_OUT, D_WR1_TLB_PFN_OUT_BEHAV;
wire D_WR1_TLB_WRITE_DISABLE_OUT, D_WR1_TLB_CACHE_ENABLE_OUT, D_WR1_TLB_PAGE_FAULT_OUT;
wire D_WR1_TLB_WRITE_DISABLE_OUT_BEHAV, D_WR1_TLB_CACHE_ENABLE_OUT_BEHAV, D_WR1_TLB_PAGE_FAULT_OUT_BEHAV;

wire [PFN_BIT_WIDTH-1:0]   DMA_PFN, DMA_PFN_BEHAV, KB_PFN, KB_PFN_BEHAV;

tlb_wrapper DUT (
  .ITLB_VPN(ITLB_VPN),
  .ITLB_PFN_OUT(ITLB_PFN_OUT),
  .ITLB_WRITE_DISABLE_OUT(ITLB_WRITE_DISABLE_OUT),
  .ITLB_CACHE_ENABLE_OUT(ITLB_CACHE_ENABLE_OUT),
  .ITLB_PAGE_FAULT_OUT(ITLB_PAGE_FAULT_OUT),

  .D_RD_TLB_VPN(D_RD_TLB_VPN),
  .D_RD_TLB_PFN_OUT(D_RD_TLB_PFN_OUT),
  .D_RD_TLB_WRITE_DISABLE_OUT(D_RD_TLB_WRITE_DISABLE_OUT),
  .D_RD_TLB_CACHE_ENABLE_OUT(D_RD_TLB_CACHE_ENABLE_OUT),
  .D_RD_TLB_PAGE_FAULT_OUT(D_RD_TLB_PAGE_FAULT_OUT),

  .D_WR0_TLB_VPN(D_WR0_TLB_VPN),
  .D_WR0_TLB_PFN_OUT(D_WR0_TLB_PFN_OUT),
  .D_WR0_TLB_WRITE_DISABLE_OUT(D_WR0_TLB_WRITE_DISABLE_OUT),
  .D_WR0_TLB_CACHE_ENABLE_OUT(D_WR0_TLB_CACHE_ENABLE_OUT),
  .D_WR0_TLB_PAGE_FAULT_OUT(D_WR0_TLB_PAGE_FAULT_OUT),

  .D_WR1_TLB_VPN(D_WR1_TLB_VPN),
  .D_WR1_TLB_PFN_OUT(D_WR1_TLB_PFN_OUT),
  .D_WR1_TLB_WRITE_DISABLE_OUT(D_WR1_TLB_WRITE_DISABLE_OUT),
  .D_WR1_TLB_CACHE_ENABLE_OUT(D_WR1_TLB_CACHE_ENABLE_OUT),
  .D_WR1_TLB_PAGE_FAULT_OUT(D_WR1_TLB_PAGE_FAULT_OUT),

  .DMA_PFN(DMA_PFN),
  .KB_PFN(KB_PFN)
);

tlb_wrapper_behav REF (
  .ITLB_VPN(ITLB_VPN),
  .ITLB_PFN_OUT(ITLB_PFN_OUT_BEHAV),
  .ITLB_WRITE_DISABLE_OUT(ITLB_WRITE_DISABLE_OUT_BEHAV),
  .ITLB_CACHE_ENABLE_OUT(ITLB_CACHE_ENABLE_OUT_BEHAV),
  .ITLB_PAGE_FAULT_OUT(ITLB_PAGE_FAULT_OUT_BEHAV),

  .D_RD_TLB_VPN(D_RD_TLB_VPN),
  .D_RD_TLB_PFN_OUT(D_RD_TLB_PFN_OUT_BEHAV),
  .D_RD_TLB_WRITE_DISABLE_OUT(D_RD_TLB_WRITE_DISABLE_OUT_BEHAV),
  .D_RD_TLB_CACHE_ENABLE_OUT(D_RD_TLB_CACHE_ENABLE_OUT_BEHAV),
  .D_RD_TLB_PAGE_FAULT_OUT(D_RD_TLB_PAGE_FAULT_OUT_BEHAV),

  .D_WR0_TLB_VPN(D_WR0_TLB_VPN),
  .D_WR0_TLB_PFN_OUT(D_WR0_TLB_PFN_OUT_BEHAV),
  .D_WR0_TLB_WRITE_DISABLE_OUT(D_WR0_TLB_WRITE_DISABLE_OUT_BEHAV),
  .D_WR0_TLB_CACHE_ENABLE_OUT(D_WR0_TLB_CACHE_ENABLE_OUT_BEHAV),
  .D_WR0_TLB_PAGE_FAULT_OUT(D_WR0_TLB_PAGE_FAULT_OUT_BEHAV),

  .D_WR1_TLB_VPN(D_WR1_TLB_VPN),
  .D_WR1_TLB_PFN_OUT(D_WR1_TLB_PFN_OUT_BEHAV),
  .D_WR1_TLB_WRITE_DISABLE_OUT(D_WR1_TLB_WRITE_DISABLE_OUT_BEHAV),
  .D_WR1_TLB_CACHE_ENABLE_OUT(D_WR1_TLB_CACHE_ENABLE_OUT_BEHAV),
  .D_WR1_TLB_PAGE_FAULT_OUT(D_WR1_TLB_PAGE_FAULT_OUT_BEHAV),

  .DMA_PFN(DMA_PFN_BEHAV),
  .KB_PFN(KB_PFN_BEHAV)
);

integer FAILURES  = 0;
integer SUCCESSES = 0;

task check;
begin
  if (ITLB_PFN_OUT           !== ITLB_PFN_OUT_BEHAV           ||
      ITLB_WRITE_DISABLE_OUT !== ITLB_WRITE_DISABLE_OUT_BEHAV ||
      ITLB_CACHE_ENABLE_OUT  !== ITLB_CACHE_ENABLE_OUT_BEHAV  ||
      ITLB_PAGE_FAULT_OUT    !== ITLB_PAGE_FAULT_OUT_BEHAV    ||

      D_RD_TLB_PFN_OUT           !== D_RD_TLB_PFN_OUT_BEHAV           ||
      D_RD_TLB_WRITE_DISABLE_OUT !== D_RD_TLB_WRITE_DISABLE_OUT_BEHAV ||
      D_RD_TLB_CACHE_ENABLE_OUT  !== D_RD_TLB_CACHE_ENABLE_OUT_BEHAV  ||
      D_RD_TLB_PAGE_FAULT_OUT    !== D_RD_TLB_PAGE_FAULT_OUT_BEHAV    ||

      D_WR0_TLB_PFN_OUT           !== D_WR0_TLB_PFN_OUT_BEHAV           ||
      D_WR0_TLB_WRITE_DISABLE_OUT !== D_WR0_TLB_WRITE_DISABLE_OUT_BEHAV ||
      D_WR0_TLB_CACHE_ENABLE_OUT  !== D_WR0_TLB_CACHE_ENABLE_OUT_BEHAV  ||
      D_WR0_TLB_PAGE_FAULT_OUT    !== D_WR0_TLB_PAGE_FAULT_OUT_BEHAV    ||

      D_WR1_TLB_PFN_OUT           !== D_WR1_TLB_PFN_OUT_BEHAV           ||
      D_WR1_TLB_WRITE_DISABLE_OUT !== D_WR1_TLB_WRITE_DISABLE_OUT_BEHAV ||
      D_WR1_TLB_CACHE_ENABLE_OUT  !== D_WR1_TLB_CACHE_ENABLE_OUT_BEHAV  ||
      D_WR1_TLB_PAGE_FAULT_OUT    !== D_WR1_TLB_PAGE_FAULT_OUT_BEHAV    ||
      
      DMA_PFN                    !== DMA_PFN_BEHAV                    ||
      KB_PFN                     !== KB_PFN_BEHAV)                    begin

    FAILURES = FAILURES + 1;
    $display("FAILURE AT TIME %t", $time);
    $display("ITLB VPN=%h PFN %h vs %h", ITLB_VPN, ITLB_PFN_OUT, ITLB_PFN_OUT_BEHAV);
    $display("DRD VPN=%h PFN %h vs %h", D_RD_TLB_VPN, D_RD_TLB_PFN_OUT, D_RD_TLB_PFN_OUT_BEHAV);
    $display("DWR0 VPN=%h PFN %h vs %h", D_WR0_TLB_VPN, D_WR0_TLB_PFN_OUT, D_WR0_TLB_PFN_OUT_BEHAV);
    $display("DWR1 VPN=%h PFN %h vs %h\n", D_WR1_TLB_VPN, D_WR1_TLB_PFN_OUT, D_WR1_TLB_PFN_OUT_BEHAV);
    $display("DMA PFN %h vs %h\n", DMA_PFN, DMA_PFN_BEHAV);
    $display("KB PFN %h vs %h\n", KB_PFN, KB_PFN_BEHAV);

  end else begin
    SUCCESSES = SUCCESSES + 1;
  end
end
endtask

initial begin
  ITLB_VPN = ~(20'h02000);
  D_RD_TLB_VPN = ~(20'h02000);
  D_WR0_TLB_VPN = ~(20'h02000);
  D_WR1_TLB_VPN = ~(20'h02000);
  #5;
  check();

  ITLB_VPN = 20'h02000;
  D_RD_TLB_VPN = 20'h02000;
  D_WR0_TLB_VPN = 20'h02000;
  D_WR1_TLB_VPN = 20'h02000;
  #5;
  check();

  repeat (1 << (VPN_BIT_WIDTH - 4)) begin
    #5;
    check();
    ITLB_VPN = ITLB_VPN + 1;
    D_RD_TLB_VPN = D_RD_TLB_VPN + 1;
    D_WR0_TLB_VPN = D_WR0_TLB_VPN + 1;
    D_WR1_TLB_VPN = D_WR1_TLB_VPN + 1;
  end

  repeat (1 << 8) begin
    #5;
    check();
    ITLB_VPN = $random;
    D_RD_TLB_VPN = $random;
    D_WR0_TLB_VPN = $random;
    D_WR1_TLB_VPN = $random;
  end

  #5;
  $display("FAILURES  = %d out of %d", FAILURES, FAILURES + SUCCESSES);
  $display("SUCCESSES = %d out of %d", SUCCESSES, FAILURES + SUCCESSES);
  $finish;
end

endmodule